<?php
namespace App\Jobs;
use App\Models\ActivityLog;use App\Models\ApplicationDeployment;use App\Models\Backup;use App\Models\DockerImage;use App\Services\Docker\DockerService;use App\Services\Operations\BackupService;use App\Services\Operations\OperationsLogService;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Queue\Queueable;use Throwable;
class UpdateDockerImageJob implements ShouldQueue{use Queueable;public int $timeout=1200;public function __construct(public int $imageId,public int $tenantId,public ?int $userId=null,public bool $safetyBackup=true){$this->onQueue(config('infrastructure.queues.deployments'));}public function handle(DockerService $docker,BackupService $backups,OperationsLogService $logs):void{$image=DockerImage::where('tenant_id',$this->tenantId)->findOrFail($this->imageId);$oldDigest=$image->digest;$deployment=ApplicationDeployment::where('tenant_id',$this->tenantId)->where('server_id',$image->server_id)->where('docker_image',$image->repository)->first();try{if($this->safetyBackup&&$deployment){$backup=Backup::create(['tenant_id'=>$this->tenantId,'application_deployment_id'=>$deployment->id,'server_id'=>$deployment->server_id,'created_by'=>$this->userId,'name'=>$deployment->name.' pre-update safety backup','backup_type'=>'full','status'=>'running','started_at'=>now()]);$backups->create($backup);}$docker->pull($image);foreach($image->server->containers()->where('image','like',$image->repository.':%')->get()as$container)$docker->container($container,'restart');$image->update(['digest'=>'sha256:'.substr(hash('sha256',$image->repository.now()),0,32),'update_available'=>false]);$logs->write($this->tenantId,'container','info',$image->repository.' updated successfully',['server_id'=>$image->server_id,'source'=>'updater']);ActivityLog::create(['tenant_id'=>$this->tenantId,'user_id'=>$this->userId,'action'=>'image.updated','description'=>$image->repository.':'.$image->tag.' updated','subject_type'=>DockerImage::class,'subject_id'=>$image->id]);}catch(Throwable $e){$image->update(['digest'=>$oldDigest,'status'=>'available','update_available'=>true]);$logs->write($this->tenantId,'container','error','Update failed and image metadata rolled back: '.$e->getMessage(),['server_id'=>$image->server_id,'source'=>'updater']);throw$e;}}}
